INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Baca Wiring Kontrol & Daya','Belum bisa baca', 'hanya baca wiring kontrol', 'bisa baca rangkaian kontrol & daya', 'bisa baca dan membuat / menggambar rangkaian kontrol daya', 'bisa baca dan membuat / menggambar rangkaian kontrol daya menggunakan aplikasi');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Basic Sensor, Actuator','Belum memahami', 'memahami tapi belum bisa instalasi', 'memahami sekaligus bisa instalasi set fungsional belum paham', 'memahami sekaligus bisa instalasi set fungsional sudah paham', 'memahami sekaligus bisa instalasi set fungsional sudah paham dan mengetahui persamaan tipe penggantinya');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Basic Inverter','Belum memahami', 'memahami tapi belum bisa instalasi', 'memahami sekaligus bisa instalasi set fungsional belum paham', 'memahami sekaligus bisa instalasi set fungsional sudah paham', 'memahami sekaligus bisa instalasi set fungsional sudah paham dan mengetahui persamaan tipe penggantinya');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Basic PLC','Belum memahami', 'memahami tapi belum bisa instalasi', 'memahami sekaligus bisa instalasi basic ladder belum paham', 'memahami sekaligus bisa instalasi basic ladder paham', 'memahami sekaligus bisa instalasi basic ladder paham + logika interlock');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Basic Instrument Analog','Belum memahami', 'memahami tapi belum bisa instalasi', 'memahami sekaligus bisa instalasi set fungsional belum paham', 'memahami sekaligus bisa instalasi set fungsional sudah paham', 'memahami sekaligus bisa instalasi set fungsional sudah paham dan mengetahui persamaan tipe penggantinya');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Basic Servo','Belum memahami', 'memahami tapi belum bisa instalasi', 'memahami sekaligus bisa instalasi set fungsional belum paham', 'memahami sekaligus bisa instalasi set fungsional sudah paham', 'memahami sekaligus bisa instalasi set fungsional sudah paham dan mengetahui persamaan tipe penggantinya');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Basic HMI','Belum memahami', 'memahami tapi belum bisa instalasi', 'memahami sekaligus bisa instalasi , create design belum bisa', 'memahami sekaligus bisa instalasi , create design bisa , set kom dg PLC belum bisa', 'memahami sekaligus bisa instalasi , create design bisa , bisa set kom dg PLC');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Intermediate Inverter','Bisa Basic Inverter 1 merk', 'Bisa Basic Inverter 3 merk', 'Bisa Basic Inverter > 5 merk', 'Bisa Basic Inverter > 5 merk + set + instalasi fitur special ( Profibus, Profinet, modbus ) 1 merk', 'Bisa Basic Inverter > 5 merk + set + instalasi fitur special ( Profibus, Profinet, modbus ) 1 merk & bisa set dg PLC nya');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Intermediate PLC','bisa basic ladder PLC 1 merk', 'bisa basic ladder PLC 3 merk', 'bisa basic ladder PLC >5 merk', 'bisa basic ladder PLC >5 merk + memfungsikan spesial function > 10 ( 1 merk )', 'bisa basic ladder PLC >5 merk + memfungsikan spesial function > 20 ( 1 merk )');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Intermediate instrument Analog','Bisa basic instrument Analog 1 merk', 'Bisa basic instrument Analog 3 merk', 'Bisa basic instrument Analog >5 merk', 'Bisa basic instrument Analog >5 merk + set kalibrasi dengan PLC', 'Bisa basic instrument Analog >5 merk + set kalibrasi dengan PLC dan bisa mengganti tipe persamaannya');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Intermediate Servo','Bisa Basic Servo 1 merk', 'Bisa Basic Servo 3 merk', 'Bisa Basic Servo >5 merk', 'Bisa Basic Servo >5 merk + instalasi fitur spesial', 'Bisa Basic Servo >5 merk + instalasi fitur spesial dan bisa mengganti tipe persamaannya');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Intermediate HMI','bisa basic HMI 1 merk', 'bisa basic HMI 3 merk', 'bisa basic HMI >5 merk', 'bisa basic HMI >5 merk & belum bisa Migrasi', 'bisa basic HMI >5 merk &  bisa Migrasi');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Analisa trobel shooting elektrikal','belum bisa analisa', 'bisa analisa lebih dari 5 jam', 'bisa analisa kurang dari 5 jam', 'bisa analisa kurang dari 5 jam + memberikan alternatif solusi tercepatnya', 'bisa analisa kurang dari 90 menit + memberikan alternatif solusi tercepatnya');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('Basic PLC WEB','Mengerti partnya, tapi Belum memahami', 'memahami tapi belum bisa instalasi', 'memahami sekaligus bisa instalasi basic ladder belum paham', 'memahami sekaligus bisa instalasi basic ladder paham', 'memahami sekaligus bisa instalasi basic ladder paham + logika interlock');
INSERT INTO skill (nama_skill,level_1, level_2, level_3, level_4, level_5) VALUES ('SET THERMAL','Mengerti partnya, tapi Belum memahami', 'memahami tapi belum bisa instalasi', 'memahami sekaligus bisa instalasi basic', 'memahami sekaligus bisa instalasi basic + SET thermal sesuai nemplate motor & I nominal', 'memahami sekaligus bisa instalasi beda merk dan alternatif lainnya');
