CREATE DATABASE IF NOT EXISTS skill_monitoring CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE skill_monitoring;

DROP TABLE IF EXISTS training_peserta;
DROP TABLE IF EXISTS training;
DROP TABLE IF EXISTS penilaian_skill;
DROP TABLE IF EXISTS target_skill;
DROP TABLE IF EXISTS skill;
DROP TABLE IF EXISTS pekerja;
DROP TABLE IF EXISTS jabatan;

CREATE TABLE jabatan (
 id INT AUTO_INCREMENT PRIMARY KEY,
 nama_jabatan VARCHAR(100) NOT NULL UNIQUE,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE pekerja (
 id INT AUTO_INCREMENT PRIMARY KEY,
 nama VARCHAR(150) NOT NULL,
 nik VARCHAR(50) NULL,
 id_jabatan INT NOT NULL,
 departemen VARCHAR(100) DEFAULT 'Teknik',
 status ENUM('Aktif','Nonaktif') DEFAULT 'Aktif',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 FOREIGN KEY (id_jabatan) REFERENCES jabatan(id)
) ENGINE=InnoDB;

CREATE TABLE skill (
 id INT AUTO_INCREMENT PRIMARY KEY,
 nama_skill VARCHAR(200) NOT NULL UNIQUE,
 level_1 TEXT NULL,
 level_2 TEXT NULL,
 level_3 TEXT NULL,
 level_4 TEXT NULL,
 level_5 TEXT NULL,
 status ENUM('Aktif','Nonaktif') DEFAULT 'Aktif',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE target_skill (
 id INT AUTO_INCREMENT PRIMARY KEY,
 id_skill INT NOT NULL,
 id_jabatan INT NOT NULL,
 target TINYINT UNSIGNED NOT NULL DEFAULT 4,
 UNIQUE KEY uniq_target (id_skill,id_jabatan),
 FOREIGN KEY (id_skill) REFERENCES skill(id) ON DELETE CASCADE,
 FOREIGN KEY (id_jabatan) REFERENCES jabatan(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE penilaian_skill (
 id BIGINT AUTO_INCREMENT PRIMARY KEY,
 id_pekerja INT NOT NULL,
 id_skill INT NOT NULL,
 tahun YEAR NOT NULL,
 nilai TINYINT UNSIGNED NOT NULL,
 tanggal_penilaian DATE NULL,
 assessor VARCHAR(150) NULL,
 catatan TEXT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uniq_penilaian (id_pekerja,id_skill,tahun),
 FOREIGN KEY (id_pekerja) REFERENCES pekerja(id) ON DELETE CASCADE,
 FOREIGN KEY (id_skill) REFERENCES skill(id) ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE training (
 id INT AUTO_INCREMENT PRIMARY KEY,
 nama_training VARCHAR(200) NOT NULL,
 id_skill INT NULL,
 trainer VARCHAR(150) NULL,
 tanggal_mulai DATE NULL,
 tanggal_selesai DATE NULL,
 lokasi VARCHAR(200) NULL,
 status ENUM('Terjadwal','Berlangsung','Selesai','Terlambat','Dibatalkan') DEFAULT 'Terjadwal',
 catatan TEXT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY (id_skill) REFERENCES skill(id) ON DELETE SET NULL
) ENGINE=InnoDB;

CREATE TABLE training_peserta (
 id INT AUTO_INCREMENT PRIMARY KEY,
 id_training INT NOT NULL,
 id_pekerja INT NOT NULL,
 nilai_sebelum TINYINT UNSIGNED NULL,
 nilai_sesudah TINYINT UNSIGNED NULL,
 hasil ENUM('Belum Dinilai','Lulus','Perlu Pengulangan') DEFAULT 'Belum Dinilai',
 catatan TEXT NULL,
 UNIQUE KEY uniq_peserta (id_training,id_pekerja),
 FOREIGN KEY (id_training) REFERENCES training(id) ON DELETE CASCADE,
 FOREIGN KEY (id_pekerja) REFERENCES pekerja(id) ON DELETE CASCADE
) ENGINE=InnoDB;
USE skill_monitoring;

